import {Ajv} from 'ajv/dist/ajv.js';
import type {DefinedError, ValidateFunction} from 'ajv/dist/ajv.js';

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        const {inputSchema} = resolved;
        const compiled = this.ajv.compile(inputSchema);
        validator = compiled;
        this.validators.set(inputSchema, compiled);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input as described in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    let validator = tool.validator;
    if (!validator) {
      const {inputSchema} = this.resolveDefinition(tool.definitionSource);
      const compiled = this.validators.get(inputSchema) ?? this.ajv.compile(inputSchema);
      this.validators.set(inputSchema, compiled);
      validator = compiled;
    }
    if (!validator(input)) {
      const details = (validator.errors ?? [])
        .map(error => {
          const detail = error as DefinedError;
          const missingProperty = detail.keyword === 'required' ? detail.params.missingProperty : undefined;
          const escapedTilde = missingProperty?.replace(/~/g, '~0');
          const escapedProperty = escapedTilde?.replace(/\//g, '~1');
          const path =
            escapedProperty === undefined ? detail.instancePath : `${detail.instancePath}/${escapedProperty}`;
          return `${path || '/'} ${error.message ?? error.keyword}`;
        })
        .join('; ');
      log.warn('tool', 'input validation failed', {name, details});
      return {result: `Invalid tool input: ${details}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by: rejects missing required input before execution specs/hal-engine-tool-input-validation/spec.md#1](../../src/orchestration/tools/registry.rejection.test.ts#L5)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input and extra properties unchanged specs/hal-engine-tool-input-validation/spec.md#3](../../src/orchestration/tools/registry.passthrough.test.ts#L5), [validated by: rejects values outside the declared enum specs/hal-engine-tool-input-validation/spec.md#3](../../src/orchestration/tools/registry.enum.test.ts#L5)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws for an unknown tool specs/hal-engine-tool-input-validation/spec.md#4](../../src/orchestration/tools/registry.unknown.test.ts#L4)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [validated by: rejects an invalid static schema at registration specs/hal-engine-tool-input-validation/spec.md#6](../../src/orchestration/tools/registry.test.ts#L4)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reads a static schema once and reuses it specs/hal-engine-tool-input-validation/spec.md#7](../../src/orchestration/tools/registry.static-cache.test.ts#L4)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: caches dynamic schemas by object reference specs/hal-engine-tool-input-validation/spec.md#8](../../src/orchestration/tools/registry.dynamic.test.ts#L5)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

- Required-property paths use JSON Pointer escaping for property names containing `~` or `/` ([validated by: escapes required property paths specs/hal-engine-tool-input-validation/spec.md#10](../../src/orchestration/tools/registry.path.test.ts#L4)).
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema compilation', () => {
  it('rejects an invalid static schema at registration specs/hal-engine-tool-input-validation/spec.md#6', () => {
    const registry = new ToolRegistry();
    expect(() =>
      registry.register(
        {name: 'broken', description: 'Invalid schema', inputSchema: {type: 'invalid'}},
        async () => 'unused'
      )
    ).toThrow(/broken/);
  });
});
